    tiling.set_batchSize(batch);
    tiling.set_featureSize(feat);
    tiling.set_tileNum(DEFAULT_TILE_NUM);

    // 从属性读取缩放因子
    float scale_factor = 1.0f;
    auto attr_sf = context->GetAttrs();
    if (attr_sf != nullptr) {
        // 获取名为 "scale_factor" 的浮点属性（若不存在则使用默认值1.0）
